"""email_validator.py

Функція практичної валідації email-адреси з детальною причиною відмови.

Контракт:
    validate_email(email) -> dict з ключами:
        - is_valid: bool
        - reason: str | None

Якщо is_valid == True, reason завжди None.

Причини відмови (reason):
    type_invalid
    empty
    has_outer_whitespace
    at_symbol_count_invalid
    local_part_missing
    domain_missing
    email_too_long
    local_part_too_long
    local_part_invalid_chars
    local_part_dot_placement_invalid
    domain_invalid_chars
    domain_no_tld
    domain_dot_placement_invalid
    domain_label_length_invalid
    domain_label_invalid_chars
    domain_label_hyphen_placement_invalid

Це не повна реалізація RFC 5322/6531. Quoted local-part ("...")
та escape (\\) не підтримуються за вимогою.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Dict, Any


@dataclass(frozen=True)
class EmailValidationResult:
    is_valid: bool
    reason: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {"is_valid": self.is_valid, "reason": self.reason}


def _invalid(reason: str) -> EmailValidationResult:
    return EmailValidationResult(False, reason)


def _has_control_char(s: str) -> bool:
    # ASCII control chars: 0-31 and DEL (127)
    for ch in s:
        o = ord(ch)
        if o < 32 or o == 127:
            return True
    return False


def validate_email(email) -> Dict[str, Any]:
    """Validate email according to the provided spec.

    The input is treated "as is": no trimming, no lowercasing.

    Args:
        email: expected str.

    Returns:
        dict: {"is_valid": bool, "reason": str|None}
    """
    # (2) type check
    if not isinstance(email, str):
        return _invalid("type_invalid").to_dict()

    # (3) empty or whitespace-only
    if email == "" or email.strip() == "":
        return _invalid("empty").to_dict()

    # (4) reject outer whitespace; do NOT trim
    if email[0].isspace() or email[-1].isspace():
        return _invalid("has_outer_whitespace").to_dict()

    # (8) total length
    if len(email) > 254:
        return _invalid("email_too_long").to_dict()

    # (5) exactly one @
    if email.count("@") != 1:
        return _invalid("at_symbol_count_invalid").to_dict()

    local, domain = email.split("@")

    # (6) local missing
    if local == "":
        return _invalid("local_part_missing").to_dict()

    # (7) domain missing
    if domain == "":
        return _invalid("domain_missing").to_dict()

    # (9) local length
    if len(local) > 64:
        return _invalid("local_part_too_long").to_dict()

    # (10) local invalid chars: spaces, control chars, '"' or '\\'
    if any(ch.isspace() for ch in local) or _has_control_char(local) or ('"' in local) or ("\\" in local):
        return _invalid("local_part_invalid_chars").to_dict()

    # (11) local dot placement
    if local.startswith(".") or local.endswith(".") or ".." in local:
        return _invalid("local_part_dot_placement_invalid").to_dict()

    # (12) domain invalid chars: spaces, control chars, non-ascii
    if any(ch.isspace() for ch in domain) or _has_control_char(domain) or any(ord(ch) > 127 for ch in domain):
        return _invalid("domain_invalid_chars").to_dict()

    # (13) must contain a dot
    if "." not in domain:
        return _invalid("domain_no_tld").to_dict()

    # (14) domain dot placement
    if domain.startswith(".") or domain.endswith("\.") or ".." in domain:
        return _invalid("domain_dot_placement_invalid").to_dict()

    labels = domain.split(".")

    # (15) label length 1..63
    for label in labels:
        if not (1 <= len(label) <= 63):
            return _invalid("domain_label_length_invalid").to_dict()

    # (16) allowed chars: letters/digits/hyphen only
    for label in labels:
        for ch in label:
            if not ("a" <= ch <= "z" or "A" <= ch <= "Z" or "0" <= ch <= "9" or ch == "-"):
                return _invalid("domain_label_invalid_chars").to_dict()

    # (17) hyphen placement
    for label in labels:
        if label.startswith("-") or label.endswith("-"):
            return _invalid("domain_label_hyphen_placement_invalid").to_dict()

    return EmailValidationResult(True, None).to_dict()

