import unittest

from email_validator import validate_email


class TestEmailValidatorAcceptance(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(validate_email("user@example.com"), {"is_valid": True, "reason": None})

    def test_type_invalid(self):
        self.assertEqual(validate_email(None), {"is_valid": False, "reason": "type_invalid"})

    def test_empty(self):
        self.assertEqual(validate_email(""), {"is_valid": False, "reason": "empty"})
        self.assertEqual(validate_email("   "), {"is_valid": False, "reason": "empty"})

    def test_outer_whitespace(self):
        self.assertEqual(validate_email(" user@example.com"), {"is_valid": False, "reason": "has_outer_whitespace"})
        self.assertEqual(validate_email("user@example.com "), {"is_valid": False, "reason": "has_outer_whitespace"})

    def test_at_symbol_count_invalid(self):
        self.assertEqual(validate_email("user@@example.com"), {"is_valid": False, "reason": "at_symbol_count_invalid"})
        self.assertEqual(validate_email("userexample.com"), {"is_valid": False, "reason": "at_symbol_count_invalid"})

    def test_local_part_missing(self):
        self.assertEqual(validate_email("@example.com"), {"is_valid": False, "reason": "local_part_missing"})

    def test_domain_missing(self):
        self.assertEqual(validate_email("user@"), {"is_valid": False, "reason": "domain_missing"})

    def test_email_too_long(self):
        # 255 chars total with one '@'
        email = ("a" * 100) + "@" + ("b" * 154)
        self.assertEqual(len(email), 255)
        self.assertEqual(validate_email(email), {"is_valid": False, "reason": "email_too_long"})

    def test_local_part_too_long(self):
        email = ("a" * 65) + "@example.com"
        self.assertEqual(validate_email(email), {"is_valid": False, "reason": "local_part_too_long"})

    def test_local_part_dot_placement_invalid(self):
        self.assertEqual(validate_email("us..er@example.com"), {"is_valid": False, "reason": "local_part_dot_placement_invalid"})
        self.assertEqual(validate_email("user.@example.com"), {"is_valid": False, "reason": "local_part_dot_placement_invalid"})
        self.assertEqual(validate_email(".user@example.com"), {"is_valid": False, "reason": "local_part_dot_placement_invalid"})

    def test_domain_no_tld(self):
        self.assertEqual(validate_email("user@localhost"), {"is_valid": False, "reason": "domain_no_tld"})

    def test_domain_dot_placement_invalid(self):
        self.assertEqual(validate_email("user@example..com"), {"is_valid": False, "reason": "domain_dot_placement_invalid"})
        self.assertEqual(validate_email("user@.example.com"), {"is_valid": False, "reason": "domain_dot_placement_invalid"})
        self.assertEqual(validate_email("user@example.com."), {"is_valid": False, "reason": "domain_dot_placement_invalid"})

    def test_domain_label_hyphen_placement_invalid(self):
        self.assertEqual(validate_email("user@-example.com"), {"is_valid": False, "reason": "domain_label_hyphen_placement_invalid"})
        self.assertEqual(validate_email("user@example-.com"), {"is_valid": False, "reason": "domain_label_hyphen_placement_invalid"})

    def test_domain_label_invalid_chars(self):
        self.assertEqual(validate_email("user@exa_mple.com"), {"is_valid": False, "reason": "domain_label_invalid_chars"})

    def test_domain_label_length_invalid(self):
        email = "user@" + ("a" * 64) + ".com"
        self.assertEqual(validate_email(email), {"is_valid": False, "reason": "domain_label_length_invalid"})


class TestEmailValidatorAdditional(unittest.TestCase):
    def test_local_part_invalid_chars_quotes_backslash(self):
        self.assertEqual(validate_email('u"ser@example.com'), {"is_valid": False, "reason": "local_part_invalid_chars"})
        self.assertEqual(validate_email('u\\ser@example.com'), {"is_valid": False, "reason": "local_part_invalid_chars"})

    def test_domain_invalid_chars_non_ascii(self):
        self.assertEqual(validate_email("user@exámple.com"), {"is_valid": False, "reason": "domain_invalid_chars"})

    def test_deterministic_first_failure(self):
        # Has outer whitespace AND multiple @; must return outer whitespace because it is checked earlier.
        self.assertEqual(validate_email(" user@@example.com"), {"is_valid": False, "reason": "has_outer_whitespace"})


if __name__ == "__main__":
    unittest.main()
